KeyBundle.declaration:
export type KeyBundle = {
  publicKey: JsonWebKey
  encryptedPrivateKey: string
  privateKeyIv: string
  vaultSalt: string
}

PublicMember.declaration:
export type PublicMember = {
  id: string
  publicKey: JsonWebKey
}

ChatMember.declaration:
export type ChatMember = PublicMember & {
  username: string
  displayName: string
  role: string
  avatar_url?: string | null
}

DisplayMessage.declaration:
export type DisplayMessage = EncryptedChatMessage & {
  text: string
  pending?: boolean
  failed?: boolean
  reply_context?: (EncryptedMessageReplyContext & { text: string }) | null
}

DiscoveredUser.declaration:
export type DiscoveredUser = PublicMember & {
  username: string
  display_name: string
  avatar_url: string | null
}

SpaceCategory.declaration:
export type SpaceCategory = {
  id: string
  name: string
}

SpaceChannelRolePermission.declaration:
export type SpaceChannelRolePermission = {
  role: 'moderator' | 'member' | 'guest'
  can_view: boolean
  can_send: boolean
  can_speak: boolean
}

SpaceChannelMember.declaration:
export type SpaceChannelMember = {
  id: string
  username: string
  display_name: string
}

SpaceMember.declaration:
export type SpaceMember = {
  id: string
  username: string
  display_name: string
  role: SpaceSummary['role']
}
